selector_to_html = {"a[href=\"pycmplot_python_api.html#Example-plotting\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Example plotting<a class=\"headerlink\" href=\"#Example-plotting\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Important notes<a class=\"headerlink\" href=\"#Important-notes\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#QQ-Plotting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">QQ-Plotting<a class=\"headerlink\" href=\"#QQ-Plotting\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Overlaying multiple<a class=\"headerlink\" href=\"#Overlaying-multiple\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#Plot-in-panels\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Plot in panels<a class=\"headerlink\" href=\"#Plot-in-panels\" title=\"Link to this heading\">\uf0c1</a></h1>", "a[href=\"pycmplot_python_api.html#Generating-circular-plots\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generating circular plots<a class=\"headerlink\" href=\"#Generating-circular-plots\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Controling the inner circle size<a class=\"headerlink\" href=\"#Controling-the-inner-circle-size\" title=\"Link to this heading\">\uf0c1</a></h3><h4>We can make it look better by placing chrom labels outside, and excluding plot title and track labels<a class=\"headerlink\" href=\"#We-can-make-it-look-better-by-placing-chrom-labels-outside,-and-excluding-plot-title-and-track-labels\" title=\"Link to this heading\">\uf0c1</a></h4>", "a[href=\"pycmplot_python_api.html#Handling-other-use-cases-and-QQ-plots\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Handling other use cases and QQ-plots<a class=\"headerlink\" href=\"#Handling-other-use-cases-and-QQ-plots\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Summary stats without <strong>BUILD</strong> column and no <code class=\"docutils literal notranslate\"><span class=\"pre\">build</span></code> information provided<a class=\"headerlink\" href=\"#Summary-stats-without-BUILD-column-and-no-build-information-provided\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Notice that there are only two significant variants in the table.</strong></p>", "a[href=\"pycmplot_python_api.html#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Specify groups of sumstats to load and plot in different panels<a class=\"headerlink\" href=\"#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API for the pycmplot package<a class=\"headerlink\" href=\"#Python-API-for-the-pycmplot-package\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Installation<a class=\"headerlink\" href=\"#Installation\" title=\"Link to this heading\">\uf0c1</a></h2><p>Follow instructions in <a class=\"reference external\" href=\"https://pypi.org/project/pycmplot/\">https://pypi.org/project/pycmplot/</a></p>", "a[href=\"pycmplot_python_api.html#Supplying-builds-with-summary-stats\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supplying builds with summary stats<a class=\"headerlink\" href=\"#Supplying-builds-with-summary-stats\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Import-the-package-functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Import the package functions<a class=\"headerlink\" href=\"#Import-the-package-functions\" title=\"Link to this heading\">\uf0c1</a></h2><p>Eight main functions are involved in generating plots</p>", "a[href=\"pycmplot_python_api.html#Getting-help\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Getting help<a class=\"headerlink\" href=\"#Getting-help\" title=\"Link to this heading\">\uf0c1</a></h2><p>To see the options of a function, simply run <code class=\"docutils literal notranslate\"><span class=\"pre\">help(function_name)</span></code></p><p>Example:</p>", "a[href=\"pycmplot_python_api.html#Generating-a-linear-plot\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generating a linear plot<a class=\"headerlink\" href=\"#Generating-a-linear-plot\" title=\"Link to this heading\">\uf0c1</a></h2><h3>No highlighting of significant loci<a class=\"headerlink\" href=\"#No-highlighting-of-significant-loci\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#Summary-stats-without-BUILD-column-and-no-build-information-provided\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Summary stats without <strong>BUILD</strong> column and no <code class=\"docutils literal notranslate\"><span class=\"pre\">build</span></code> information provided<a class=\"headerlink\" href=\"#Summary-stats-without-BUILD-column-and-no-build-information-provided\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Notice that there are only two significant variants in the table.</strong></p>", "a[href=\"pycmplot_python_api.html#Installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#Installation\" title=\"Link to this heading\">\uf0c1</a></h2><p>Follow instructions in <a class=\"reference external\" href=\"https://pypi.org/project/pycmplot/\">https://pypi.org/project/pycmplot/</a></p>", "a[href=\"pycmplot_python_api.html#Important-notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Important notes<a class=\"headerlink\" href=\"#Important-notes\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Highlighting-significant-loci-and-annotating-by-SNP\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Highlighting significant loci and annotating by SNP<a class=\"headerlink\" href=\"#Highlighting-significant-loci-and-annotating-by-SNP\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Highlighting by a different p-value threshold and changing plot colors and removing track labels<a class=\"headerlink\" href=\"#Highlighting-by-a-different-p-value-threshold-and-changing-plot-colors-and-removing-track-labels\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"pycmplot_python_api.html#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Generating a linear plot<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Multi-panel-Circular-Manhattan-Plotting\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-panel Circular Manhattan Plotting<a class=\"headerlink\" href=\"#Multi-panel-Circular-Manhattan-Plotting\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Specify groups of sumstats to load and plot in different panels<a class=\"headerlink\" href=\"#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html#Final-Notes\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Final Notes<a class=\"headerlink\" href=\"#Final-Notes\" title=\"Link to this heading\">\uf0c1</a></h1>", "a[href=\"#python-api-notebook\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API Tutorial<a class=\"headerlink\" href=\"#python-api-notebook\" title=\"Link to this heading\">\uf0c1</a></h1><p>The interactive tutorial below demonstrates the full Python API using real\nsummary statistics data. It covers data loading, single- and multi-track\nlinear Manhattan plots, circular Manhattan plots, liftover, and the hits\nsummary table.</p>", "a[href=\"pycmplot_python_api.html#Ensuring-all-highlighted-loci-are-also-annotated\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Ensuring all highlighted loci are also annotated<a class=\"headerlink\" href=\"#Ensuring-all-highlighted-loci-are-also-annotated\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Explicitly speficying directory where output files should be stored<a class=\"headerlink\" href=\"#Explicitly-speficying-directory-where-output-files-should-be-stored\" title=\"Link to this heading\">\uf0c1</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tippy');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: true, theme: 'light-border',

            });
        };
    };
    console.log("tippy tips loaded!");
};
